package main

import (
	"embed"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
)

// These binaries are generated by deploy.sh immediately before building the app.
//go:embed bundled/autoipo bundled/chrome-extension-cli
var bundledHelpers embed.FS

func installBundledHelpers(root string) error {
	binDir := filepath.Join(root, "bin")
	if err := os.MkdirAll(binDir, 0o755); err != nil {
		return fmt.Errorf("create helper binary directory: %w", err)
	}
	for _, name := range []string{"autoipo", "chrome-extension-cli"} {
		data, err := fs.ReadFile(bundledHelpers, filepath.Join("bundled", name))
		if err != nil {
			return fmt.Errorf("read bundled %s: %w", name, err)
		}
		destination := filepath.Join(binDir, name)
		tempFile := destination + ".new"
		if err := os.WriteFile(tempFile, data, 0o755); err != nil {
			return fmt.Errorf("write bundled %s: %w", name, err)
		}
		if err := os.Rename(tempFile, destination); err != nil {
			_ = os.Remove(tempFile)
			return fmt.Errorf("install bundled %s: %w", name, err)
		}
	}
	return nil
}
